def compute(vars):
    trading_assets_excluding_derivatives = vars["v1"]
    trading_liabilities_excluding_derivatives = vars["v2"]
    net_trading_assets = (
        trading_assets_excluding_derivatives
        - trading_liabilities_excluding_derivatives
    )

    return {
        "value": net_trading_assets,
        "trace": {
            "trading_assets_excluding_derivatives": trading_assets_excluding_derivatives,
            "trading_liabilities_excluding_derivatives": trading_liabilities_excluding_derivatives,
            "output_meta": {
                "currency": "USD",
                "scale": "million",
                "unit": None
            }
        }
    }
